// Bounded browser CMake evaluation. Never executes host processes or fetches code.
export function evaluateCMake(files,parse,{board='pico',architecture='arm'}={}){
 const input=new Map(files.map(f=>[f.name,f.content])),output=new Map(input),generated=new Map(),functions=new Map(),active=new Set(),guards=new Set();let budget=10000;
 const norm=(base,name)=>{if(/^(?:[A-Za-z]:|\/|\\)|\\|\$|[<>]/.test(name))throw Error('Proje dışı/çözümlenmemiş CMake yolu: '+name);const p=[];for(const s of (base+'/'+name).split('/')){if(!s||s==='.')continue;if(s==='..'){if(!p.length)throw Error('Proje dışına çıkılamaz.');p.pop();}else p.push(s);}return p.join('/')||'.';};
 const truth=v=>!(Number.isFinite(+v)&&+v===0)&&!(/^(?:|0|OFF|NO|FALSE|N|IGNORE|NOTFOUND)$/i.test(v)||/-NOTFOUND$/i.test(v));
 const root=new Map(Object.entries({PICO_BOARD:board.startsWith('pico-2')?(board.includes('-w')?'pico2_w':'pico2'):(board.includes('-w')?'pico_w':'pico'),PICO_RP2040:board.startsWith('pico-2')?'0':'1',PICO_RP2350:board.startsWith('pico-2')?'1':'0',PICO_PLATFORM:board.startsWith('pico-2')?(architecture==='riscv'?'rp2350-riscv':'rp2350-arm-s'):'rp2040',CMAKE_SOURCE_DIR:'.',PROJECT_SOURCE_DIR:'.',CMAKE_BINARY_DIR:'.wirevo-cmake'}).map(([k,v])=>[k,[v]]));
 const value=(s,v)=>v.get(s)?.join(';')??s;
 const expand=(arg,v,dir)=>{let s=arg.text.replace(/\$\{([\w]+)\}/g,(_,k)=>k==='CMAKE_CURRENT_SOURCE_DIR'||k==='CMAKE_CURRENT_LIST_DIR'?dir||'.':k==='CMAKE_CURRENT_BINARY_DIR'?'.wirevo-cmake'+(dir?'/'+dir:''):v.get(k)?.join(';')??'');if(/\$/.test(s))throw Error('Ortam/generator ifadesi desteklenmiyor.');return arg.quoted?[s]:s.split(';').filter(Boolean);};
 function condition(tokens,v){if(!tokens.length)return false;const args=tokens.map(t=>t.text),get=j=>tokens[j].quoted?args[j]:value(args[j],v);let i=0;const atom=()=>{if(i>=args.length)throw Error('Eksik if koşulu');if(args[i]==='NOT'){i++;return !atom();}if(args[i]==='DEFINED'){i++;return v.has(args[i++]);}let a=get(i++);const op=args[i];if(['STREQUAL','EQUAL','LESS','GREATER','LESS_EQUAL','GREATER_EQUAL'].includes(op)){i++;if(i>=args.length)throw Error('Eksik karşılaştırma');const b=get(i++);if(op==='STREQUAL')return a===b;if(!Number.isFinite(+a)||!Number.isFinite(+b))throw Error('Sayısal koşul geçersiz');return {EQUAL:+a===+b,LESS:+a<+b,GREATER:+a>+b,LESS_EQUAL:+a<=+b,GREATER_EQUAL:+a>=+b}[op];}return !tokens[i-1].quoted&&v.has(args[i-1])?truth(a):/^(?:ON|YES|TRUE|Y)$/i.test(a)||Number.isFinite(+a)&&+a!==0;};let result=atom();while(i<args.length){const op=args[i++];if(!['AND','OR'].includes(op))throw Error('Desteklenmeyen koşul: '+op);const next=atom();result=op==='AND'?result&&next:result||next;}return result;}
 const serialize=(cmd,a)=>cmd.name+'('+a.map(s=>'"'+s.replace(/\\/g,'\\\\').replace(/"/g,'\\"')+'"').join(' ')+')';
 function run(cmds,v,dir,parent,emit,depth=0){if(depth>32)throw Error('CMake çağrı derinliği sınırı');for(let i=0;i<cmds.length;i++){const c=cmds[i];if(--budget<0)throw Error('CMake işlem sınırı aşıldı');try{const a=c.args.flatMap(x=>expand(x,v,dir)),[name,...rest]=a;
   if(['if','function','foreach'].includes(c.name)){const endName={if:'endif',function:'endfunction',foreach:'endforeach'}[c.name];let end=i+1,nested=0;const cuts=[i];for(;end<cmds.length;end++){if(cmds[end].name===c.name)nested++;if(cmds[end].name===endName){if(!nested)break;nested--;}if(c.name==='if'&&!nested&&['else','elseif'].includes(cmds[end].name))cuts.push(end);}if(end===cmds.length)throw Error('Kapanmayan '+c.name);cuts.push(end);
    if(c.name==='function'){if(!name||!/^\w+$/.test(name))throw Error('Fonksiyon adı geçersiz');functions.set(name.toLowerCase(),{params:rest,body:cmds.slice(i+1,end)});}
    else if(c.name==='if'){let chosen=false;for(let j=0;j<cuts.length-1;j++){const branch=cmds[cuts[j]];if(chosen)break;const args=branch.args.flatMap(x=>expand(x,v,dir).map(text=>({text,quoted:x.quoted})));if(branch.name==='else'||condition(args,v)){run(cmds.slice(cuts[j]+1,cuts[j+1]),v,dir,parent,emit,depth+1);chosen=true;}}}
    else{if(!name||rest[0]!=='IN'||!['ITEMS','LISTS'].includes(rest[1]))throw Error('foreach VAR IN ITEMS/LISTS gerekli');const items=rest[1]==='ITEMS'?rest.slice(2):rest.slice(2).flatMap(k=>v.get(k)||[]);if(items.length>256)throw Error('foreach sınırı');const old=v.get(name),had=v.has(name);for(const item of items){v.set(name,[item]);run(cmds.slice(i+1,end),v,dir,parent,emit,depth+1);}if(had)v.set(name,old);else v.delete(name);}i=end;continue;}
   if(functions.has(c.name)){const f=functions.get(c.name);if(a.length<f.params.length)throw Error('Eksik fonksiyon argümanı');const scope=new Map(v);f.params.forEach((p,j)=>scope.set(p,[a[j]]));scope.set('ARGC',[String(a.length)]);scope.set('ARGV',a);scope.set('ARGN',a.slice(f.params.length));a.forEach((s,j)=>scope.set('ARGV'+j,[s]));run(f.body,scope,dir,v,emit,depth+1);continue;}
   if(c.name==='set'){if(!name||rest.some(x=>['CACHE','FORCE'].includes(x)))throw Error('CACHE/FORCE desteklenmiyor');if(rest.at(-1)==='PARENT_SCOPE'){if(!parent)throw Error('Üst değişken kapsamı yok');parent.set(name,rest.slice(0,-1));}else v.set(name,rest);continue;}
   if(c.name==='unset'){if(a.length!==1)throw Error('unset tek yerel değişken alır');v.delete(name);continue;}
   if(c.name==='option'){if(a.length<2||a.length>3)throw Error('option NAME HELP [ON/OFF]');if(!v.has(name))v.set(name,[rest[1]||'OFF']);continue;}
   if(c.name==='list'){const [op,k,...items]=a;if(op!=='APPEND'||!k)throw Error('Yalnız list(APPEND) desteklenir');v.set(k,[...(v.get(k)||[]),...items]);continue;}
   if(c.name==='include_guard'){if(a.length!==1||a[0]!=='GLOBAL')throw Error('include_guard(GLOBAL) gerekli');continue;}
   if(c.name==='include'||c.name==='add_subdirectory'){if(a.length!==1)throw Error('Tek yerel dosya/klasör gerekli');if(c.name==='include'&&name==='pico_sdk_import.cmake')continue;const file=norm(dir,name)+(c.name==='add_subdirectory'?'/CMakeLists.txt':'');const child=c.name==='add_subdirectory'?new Map(v):v;if(read(file,child,c.name==='add_subdirectory'?v:parent)!==false)emit(serialize(c,a));continue;}
   if(c.name==='configure_file'){if(a.length<2||rest.slice(1).some(x=>!['@ONLY','COPYONLY'].includes(x)))throw Error('configure_file yalnız @ONLY/COPYONLY destekler');const src=norm(dir,name),dst=rest[0].startsWith('.wirevo-cmake/')?norm('',rest[0]):norm('.wirevo-cmake'+(dir?'/'+dir:''),rest[0]);if(!dst.startsWith('.wirevo-cmake/'))throw Error('Çıktı derleme klasörü dışına çıkamaz');if(!input.has(src))throw Error('Şablon bulunamadı: '+src);if(!/\.(h|c)$/.test(dst)||generated.has(dst))throw Error('Üretilen dosya geçersiz/yineleniyor');let text=input.get(src);if(!rest.includes('COPYONLY')){text=text.replace(/^([ \t]*)#[ \t]*cmakedefine(01)?[ \t]+(\w+)([^\n]*)/gm,(_,space,zero,k,tail)=>zero?space+'#define '+k+' '+(truth(v.get(k)?.join(';')||'')?1:0):truth(v.get(k)?.join(';')||'')?space+'#define '+k+tail:space+'/* #undef '+k+' */');const get=k=>v.get(k)?.join(';')||'';text=text.replace(/@(\w+)@/g,(_,k)=>get(k));if(!rest.includes('@ONLY'))text=text.replace(/\$\{(\w+)\}/g,(_,k)=>get(k));}if([...generated.values()].reduce((n,s)=>n+s.length,0)+text.length>100000)throw Error('Üretilen dosya sınırı');generated.set(dst,text);continue;}
   if(['else','elseif','endif','endfunction','endforeach'].includes(c.name))throw Error('Eşleşmeyen '+c.name);
   if(c.name==='project'&&name){v.set('PROJECT_NAME',[name]);v.set(name+'_SOURCE_DIR',[dir||'.']);v.set(name+'_BINARY_DIR',['.wirevo-cmake'+(dir?'/'+dir:'')]);}
   emit(serialize(c,a));
  }catch(e){throw Error(c.file+':'+c.line+': '+e.message);}}
 }
 function read(file,v,parent){if(active.has(file))throw Error('Döngüsel CMake include: '+file);if(!input.has(file))throw Error('CMake dosyası bulunamadı: '+file);const cmds=parse(input.get(file),file);if(cmds.some(c=>c.name==='include_guard')){if(guards.has(file))return false;guards.add(file);}active.add(file);const dir=file.includes('/')?file.slice(0,file.lastIndexOf('/')):'',lines=[];run(cmds,v,dir,parent,s=>lines.push(s));output.set(file,lines.join('\n'));active.delete(file);return true;}
 if(input.has('CMakeLists.txt'))read('CMakeLists.txt',root,null);
 return {files:[...output,...generated].map(([name,content])=>({name,content})),generated:[...generated].map(([name,content])=>({name,content}))};
}
